import { RotateCcw, Upload, Play, Pause, RefreshCw } from "lucide-react";
import { useRef, useEffect, useState } from "react";
import {
  NumberControl,
  SelectControl,
  Toggle,
  Help,
  help,
} from "../ui/Controls.jsx";
import { PresetManager } from "../presets/PresetManager.jsx";
import {
  MODES,
  initialState,
  fromPreset,
} from "../../services/zernike/zernike.js";
import { decodeFile } from "../../services/zernike/images.js";
import {
  parameterHelp as H,
  coefficientHelp,
} from "../../utils/zernike-learning.js";
import { useStudioStore } from "../../store/useStudioStore.js";
import { useToast } from "../ui/Toast.jsx";
const modeOptions = MODES.map((m) => [m.j, `${m.j} · ${m.name}`]);
export const targetOptions = [
  ["text", "Testo ad alto contrasto"],
  ["usaf", "Target USAF sintetico"],
  ["siemens", "Siemens star"],
  ["bars", "Pattern a barre"],
  ["portrait", "Volto umano · NASA"],
  ["landscape", "Paesaggio sintetico"],
  ["upload", "Immagine caricata"],
];
export function ZernikeControls({
  view,
  animation,
  setAnimation,
  autoCapture,
  setAutoCapture,
  strength,
  setStrength,
  newAtmosphere,
}) {
  const p = useStudioStore((s) => s.zernike),
    update = useStudioStore((s) => s.updateZernike),
    setState = useStudioStore((s) => s.setState),
    setUploaded = useStudioStore((s) => s.setUploadedImage),
    uploaded = useStudioStore((s) => s.uploadedImage),
    toast = useToast(),
    file = useRef(null);
  const num = (key, label, min, max, step, unit) => (
    <NumberControl
      key={key}
      label={label}
      value={p[key]}
      onChange={(value) => update({ [key]: value })}
      min={min}
      max={max}
      step={step}
      unit={unit}
      entry={H[key]}
    />
  );
  const coefficient = (j, value) =>
    update((old) => ({
      coeff: old.coeff.map((a, i) => (i === j ? value : a)),
    }));
  return (
    <>
      <section className="sidebar-section">
        <div className="section-heading">
          <h3>Sistema ottico</h3>
          <button
            className="icon-button"
            aria-label="Ripristina sistema Zernike"
            onClick={() => {
              setAnimation(false);
              setState("zernike", initialState());
            }}
          >
            <RotateCcw size={16} />
          </button>
        </div>
        <SelectControl
          label="Preset ottici e oftalmici"
          value=""
          options={[
            ["", "Scegli una condizione…"],
            ["ideal", "Occhio normale · ideale"],
            ["defocus", "Defocus"],
            ["coma", "Coma orizzontale"],
            ["astigmatism", "Astigmatismo"],
            ["combined", "Coma + astigmatismo + sferica"],
            ["myopia", "Miopia · modello defocus −"],
            ["hyperopia", "Ipermetropia · defocus +"],
            ["keratoconus", "Cheratocono · esempio modale"],
          ]}
          onChange={(key) => {
            setAnimation(false);
            update({
              coeff: fromPreset(key),
              ...(["ideal", "myopia", "hyperopia", "keratoconus"].includes(key)
                ? { focal: 17, diameter: 4, pitch: 1, lambda: 550 }
                : {}),
            });
          }}
          entry={H.preset}
        />
        {num("lambda", "Lunghezza d’onda", 380, 780, 1, "nm")}
        {num("diameter", "Diametro pupillare", 1, 10, 0.1, "mm")}
        {num("focal", "Lunghezza focale", 10, 100, 0.1, "mm")}
        {num("pitch", "Passo immagine", 0.1, 4, 0.01, "µm/px")}
        <SelectControl
          label="Campioni dell’immagine"
          value={p.resolution}
          onChange={(v) => update({ resolution: Number(v) })}
          options={[
            [512, "512 × 512 · rapida"],
            [1024, "1024 × 1024 · alta"],
          ]}
          entry={H.resolution}
        />
        <SelectControl
          label="Convoluzione ai bordi"
          value={p.boundary}
          onChange={(boundary) => update({ boundary })}
          options={[
            ["periodic", "Periodica"],
            ["zero", "Zero padding · FFT 2N"],
          ]}
          entry={H.boundary}
        />
      </section>
      <section className="sidebar-section">
        <h3>Oggetto osservato</h3>
        <SelectControl
          label="Immagine di test"
          value={p.target}
          onChange={(target) => {
            if (target === "upload" && !uploaded) {
              file.current.click();
              return;
            }
            update({ target });
          }}
          options={targetOptions}
          entry={H.target}
        />
        <div className="control-label">
          <button className="button small" onClick={() => file.current.click()}>
            <Upload size={15} /> Carica PNG, JPG, TIFF
          </button>
          <Help entry={H.upload} />
        </div>
        <input
          ref={file}
          hidden
          type="file"
          accept="image/png,image/jpeg,image/tiff,.tif,.tiff"
          onChange={async (e) => {
            try {
              const f = e.target.files[0];
              if (f) {
                setUploaded(await decodeFile(f));
                update({ target: "upload" });
                toast("Immagine caricata e convertita in luminanza lineare.");
              }
            } catch (error) {
              toast(error.message);
            }
            e.target.value = "";
          }}
        />
        <p className="tiny muted">
          Luminanza monocromatica · massimo 32 MB / 16 MP. La foto resta sul
          dispositivo.
        </p>
      </section>
      {view !== "quiz" && (
        <section className="sidebar-section">
          <div className="section-heading">
            <h3>Coefficienti di Zernike</h3>
            <button
              className="text-button"
              onClick={() => {
                setAnimation(false);
                update({ coeff: Array(15).fill(0) });
              }}
            >
              Azzera
            </button>
          </div>
          <p className="tiny muted">
            Base OSA/ANSI ortonormale · j = 0…14.
            <br />
            Valori in onde; µm = a · λ / 1000.
          </p>
          <div className="coefficients">
            {MODES.map((m) => (
              <div className="coefficient" key={m.j}>
                <NumberControl
                  label={`${m.j} · ${m.name}`}
                  value={p.coeff[m.j]}
                  onChange={(a) => coefficient(m.j, a)}
                  min={-3}
                  max={3}
                  step={0.01}
                  unit="λ"
                  entry={coefficientHelp(m.j, "waves")}
                />
                <div className="micron-row">
                  <label htmlFor={`micron-${m.j}`}>OPD del modo {m.j}</label>
                  <MicronField
                    mode={m}
                    value={(p.coeff[m.j] * p.lambda) / 1000}
                    limit={(3 * p.lambda) / 1000}
                    onChange={(value) =>
                      coefficient(m.j, (value * 1000) / p.lambda)
                    }
                  />
                  <span>µm</span>
                  <Help entry={coefficientHelp(m.j, "um")} />
                </div>
              </div>
            ))}
          </div>
        </section>
      )}
      <section className="sidebar-section">
        <h3>PSF e visualizzazione</h3>
        <Toggle
          label="PSF logaritmica"
          checked={p.log}
          onChange={(log) => update({ log })}
          entry={H.log}
        />
        {p.log && num("psfRange", "Dinamica logaritmica", 2, 8, 0.1, "decadi")}
        {num("psfZoom", "Zoom PSF", 1, 64, 1, "×")}
        <button
          className="button small"
          onClick={() => update({ psfX: 0, psfY: 0, psfZoom: 16 })}
        >
          <RotateCcw size={14} /> Ricentra PSF
        </button>
      </section>
      {view === "compare" && (
        <section className="sidebar-section">
          <h3>Condizione singola</h3>
          <SelectControl
            label="Modo da confrontare"
            value={p.comparisonMode}
            onChange={(v) => update({ comparisonMode: Number(v) })}
            options={modeOptions}
            entry={H.comparisonMode}
          />
          {num(
            "comparisonAmplitude",
            "Ampiezza del modo singolo",
            -3,
            3,
            0.01,
            "λ",
          )}
        </section>
      )}
      {view !== "quiz" && (
        <section className="sidebar-section">
          <h3>Animazione didattica</h3>
          <SelectControl
            label="Modo da animare"
            value={p.animationMode}
            onChange={(v) => update({ animationMode: Number(v) })}
            options={modeOptions}
            entry={H.animationMode}
          />
          {num("animationMax", "Ampiezza massima", 0.05, 3, 0.05, "λ")}
          {num("animationSeconds", "Durata del ciclo", 2, 60, 1, "s")}
          <Toggle
            label="Acquisizioni automatiche"
            checked={autoCapture}
            onChange={setAutoCapture}
            entry={H.autoCapture}
          />
          <button
            className={`button ${animation ? "" : "primary"}`}
            onClick={() => setAnimation(!animation)}
          >
            {animation ? <Pause size={15} /> : <Play size={15} />}{" "}
            {animation ? "Ferma animazione" : "Avvia animazione"}
          </button>
        </section>
      )}
      {view === "ao" && (
        <section className="sidebar-section">
          <h3>Ottica adattiva</h3>
          <NumberControl
            label="RMS atmosferico sintetico"
            value={strength}
            onChange={setStrength}
            min={0.05}
            max={2}
            step={0.05}
            unit="λ"
            entry={H.turbulenceStrength}
          />
          <button className="button small" onClick={newAtmosphere}>
            <RefreshCw size={15} /> Genera nuovo fronte
          </button>
          {num("aoGain", "Guadagno della correzione", 0, 1, 0.01, "")}
          {num("aoOrder", "Ultimo indice corretto", 1, 14, 1, "j")}
          <p className="tiny muted">
            Specchio modale ideale, senza rumore né ritardo. Turbolenza
            sintetica, non uno schermo Kolmogorov.
          </p>
        </section>
      )}
      <PresetManager engine="zernike" />
    </>
  );
}

function MicronField({ mode, value, limit, onChange }) {
  const [draft, setDraft] = useState(String(Number(value.toFixed(5)))),
    [focused, setFocused] = useState(false);
  useEffect(() => {
    if (!focused) setDraft(String(Number(value.toFixed(5))));
  }, [value, focused]);
  const commit = () => {
    const number = Number(draft);
    if (draft.trim() && Number.isFinite(number))
      onChange(Math.max(-limit, Math.min(limit, number)));
    else setDraft(String(value));
    setFocused(false);
  };
  return (
    <input
      id={`micron-${mode.j}`}
      aria-label={`${mode.name} in micrometri`}
      type="number"
      step={0.001}
      min={-limit}
      max={limit}
      value={draft}
      onFocus={() => setFocused(true)}
      onChange={(e) => setDraft(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => {
        if (e.key === "Enter") e.currentTarget.blur();
      }}
    />
  );
}
