import { useEffect, useState } from "react";
import { sourceCanvas, luminance } from "../services/zernike/images.js";
let revision = 0;
export function useImageSource(target, resolution, uploaded) {
  const [source, setSource] = useState(null),
    [error, setError] = useState(null);
  useEffect(() => {
    let cancelled = false;
    setSource(null);
    setError(null);
    (async () => {
      try {
        const canvas = await sourceCanvas(target, resolution, uploaded);
        const data = luminance(canvas);
        if (!cancelled) setSource({ ...data, canvas, revision: ++revision });
      } catch (e) {
        if (!cancelled) setError(e.message);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [target, resolution, uploaded]);
  return { source, error };
}
