import { useEffect, useMemo, useRef, useState } from "react";
import {
  Plus,
  Trash2,
  ArrowRight,
  RotateCcw,
  ZoomIn,
  ZoomOut,
} from "lucide-react";
import { Workspace } from "../components/layout/Shell.jsx";
import { ZernikeControls } from "../components/layout/ZernikeControls.jsx";
import {
  Panel,
  Metrics,
  Notice,
  Tabs,
  SelectControl,
  Toggle,
  Help,
  help,
} from "../components/ui/Controls.jsx";
import { ExportBar } from "../components/ui/ExportBar.jsx";
import { useToast } from "../components/ui/Toast.jsx";
import { CanvasImage, WaveMap } from "../components/visual/CanvasImage.jsx";
import { LineChart } from "../components/visual/LineChart.jsx";
import {
  ImageComparison,
  Pupil,
} from "../components/visual/ImageComparison.jsx";
import { LearningQuiz } from "../components/learning/LearningQuiz.jsx";
import { ExplorationGuide } from "../components/learning/ExplorationGuide.jsx";
import { useStudioStore } from "../store/useStudioStore.js";
import { useImageSource } from "../hooks/useImageSource.js";
import { useSimulation } from "../hooks/useSimulation.js";
import { MODES, waveMap, atmosphere } from "../services/zernike/zernike.js";
import {
  parameterHelp as H,
  explorationGuide,
} from "../utils/zernike-learning.js";
import {
  format,
  downloadBlob,
  downloadCanvas,
  makeReport,
  reportSVG,
} from "../utils/export.js";
const viewTabs = [
  ["lab", "Laboratorio"],
  ["compare", "Confronto"],
  ["fourier", "Catena di Fourier"],
  ["quiz", "Quiz"],
  ["ao", "Ottica adattiva"],
];
const heldColors = ["#dca9ff", "#ffce73", "#a4b5ff", "#ff9cb1"];
export default function ZernikePage() {
  const p = useStudioStore((s) => s.zernike),
    update = useStudioStore((s) => s.updateZernike),
    uploaded = useStudioStore((s) => s.uploadedImage),
    theme = useStudioStore((s) => s.theme),
    toast = useToast();
  const [view, setView] = useState("lab"),
    [imageMode, setImageMode] = useState("split"),
    [held, setHeld] = useState([]),
    [animation, setAnimation] = useState(false),
    [autoCapture, setAutoCapture] = useState(false),
    [captures, setCaptures] = useState([]),
    [strength, setStrength] = useState(0.6),
    [answer, setAnswer] = useState(null),
    [csvKind, setCsvKind] = useState("mtf"),
    [forceCPU, setForceCPU] = useState(false),
    [exporting, setExporting] = useState(false),
    [contributions, setContributions] = useState(false);
  const originalRef = useRef(null),
    waveRef = useRef(null),
    psfRef = useRef(null),
    idealRef = useRef(null),
    resultRef = useRef(null),
    chartRef = useRef(null),
    otfRef = useRef(null),
    drag = useRef(null),
    lastCapture = useRef(0);
  const { source, error: sourceError } = useImageSource(
    p.target,
    p.resolution,
    uploaded,
  );
  const context = useMemo(
    () => ({
      image: source,
      view: view === "compare" || view === "ao" ? view : "lab",
    }),
    [source, view],
  );
  // View-only split and animation settings must not trigger an FFT.
  const simulationParams = useMemo(
    () => p,
    [
      p.coeff,
      p.lambda,
      p.diameter,
      p.focal,
      p.pitch,
      p.resolution,
      p.boundary,
      p.log,
      p.psfRange,
      p.psfZoom,
      p.psfX,
      p.psfY,
      p.target,
      p.comparisonMode,
      p.comparisonAmplitude,
      p.aoGain,
      p.aoOrder,
    ],
  );
  const { result, busy, error, backend, exportData } = useSimulation(
    "zernike",
    simulationParams,
    context,
    { enabled: !!source && !sourceError, forceCPU },
  );
  const ready = !!result && !busy && !error && !sourceError && !!source;
  const current = result?.params || p,
    images = result?.images || {};
  const series = useMemo(() => {
    if (!result) return [];
    const physical = (values) =>
      Array.from(values, (y, k) => ({
        x: (1000 * k) / (result.n * current.pitch),
        y,
      }));
    return [
      {
        label: "Ideale · pupilla circolare",
        borderColor: "#8fa3b6",
        borderDash: [5, 4],
        data: physical(result.idealCuts.x),
      },
      {
        label: "Aberrata X",
        borderColor: "#79dfc7",
        data: physical(result.cuts.x),
      },
      {
        label: "Aberrata Y",
        borderColor: "#f1b18e",
        data: physical(result.cuts.y),
      },
      ...held.map((item, i) => ({
        label: item.label,
        borderColor: heldColors[i],
        borderDash: [3, 3],
        data: item.data,
      })),
    ].map((s) => ({ ...s, color: s.borderColor }));
  }, [result, current.pitch, held]);
  const individual = useMemo(
    () =>
      contributions && result
        ? result.effectiveCoeff.flatMap((a, j) => {
            if (!a) return [];
            const c = Array(15).fill(0);
            c[j] = a;
            return [{ j, a, map: waveMap(c, 128) }];
          })
        : [],
    [contributions, result],
  );
  useEffect(() => {
    if (!animation) return;
    const start = performance.now(),
      timer = setInterval(() => {
        const state = useStudioStore.getState().zernike,
          phase = (performance.now() - start) / (state.animationSeconds * 1000),
          a = (state.animationMax * (1 - Math.cos(phase * 2 * Math.PI))) / 2;
        update((old) => ({
          coeff: old.coeff.map((x, j) => (j === old.animationMode ? a : x)),
        }));
      }, 80);
    return () => clearInterval(timer);
  }, [animation, update]);
  useEffect(() => {
    if (
      !result ||
      error ||
      !animation ||
      !autoCapture ||
      performance.now() - lastCapture.current < 1500
    )
      return;
    lastCapture.current = performance.now();
    const canvas = makeReport({
      title: "Zernike · acquisizione automatica",
      params: current,
      metrics: [
        `RMS ${format(result.wave.rms)} λ`,
        `Strehl ${format(result.strehl)}`,
      ],
      panels: [
        { title: "Fronte d’onda", canvas: waveRef.current },
        { title: "PSF", canvas: psfRef.current },
        { title: "Immagine", canvas: resultRef.current },
      ],
      width: 1800,
    });
    setCaptures((old) =>
      [
        { url: canvas.toDataURL("image/png"), rms: result.wave.rms },
        ...old,
      ].slice(0, 6),
    );
  }, [ready, result, error, animation, autoCapture, current]);
  function generateQuiz() {
    setAnimation(false);
    const random = new Uint32Array(3);
    crypto.getRandomValues(random);
    const j = 3 + (random[0] % 12),
      a = (0.1 + (random[1] % 13) / 10) * (random[2] % 2 ? 1 : -1);
    update({ coeff: Array.from({ length: 15 }, (_, i) => (i === j ? a : 0)) });
    setAnswer({ j, a });
  }
  function changeView(next) {
    if (next === "quiz") {
      setAnimation(false);
      generateQuiz();
    }
    setView(next);
  }
  function holdCurve() {
    if (held.length >= 4) {
      toast("Massimo quattro curve memorizzate. Rimuovine una per continuare.");
      return;
    }
    setHeld((old) => [
      ...old,
      {
        label: `RMS ${format(result.wave.rms, 2)} λ · ${current.lambda} nm · D ${current.diameter}`,
        data: series[1].data.map((point) => ({ ...point })),
      },
    ]);
  }
  const newAtmosphere = () => {
    setAnimation(false);
    update({
      coeff: atmosphere(
        crypto.getRandomValues(new Uint32Array(1))[0],
        strength,
      ),
    });
  };
  const panels = () => [
    { title: "Originale", canvas: originalRef.current },
    { title: "Fronte d’onda", canvas: waveRef.current },
    { title: "PSF aberrata", canvas: psfRef.current },
    { title: "MTF", canvas: chartRef.current },
    { title: "Immagine risultante", canvas: resultRef.current },
    ...(otfRef.current
      ? [{ title: "OTF complessa", canvas: otfRef.current }]
      : []),
  ];
  const report = () =>
    makeReport({
      title: "Simulatore Aberrazioni Zernike",
      params: current,
      metrics: [
        `λ ${current.lambda} nm`,
        `RMS ${format(result.wave.rms)} λ`,
        `Strehl ${format(result.strehl, 4)}`,
        `${format(result.ms, 1)} ms`,
      ],
      panels: panels(),
    });
  async function exportCSV() {
    try {
      setExporting(true);
      const meta = `# Ottica Studio; ${JSON.stringify(current)}\n`;
      let content;
      if (csvKind === "coeff")
        content = [
          "j,n,m,nome,coeff_lambda,OPD_um",
          ...MODES.map((m) =>
            [
              m.j,
              m.n,
              m.m,
              m.name,
              result.effectiveCoeff[m.j],
              (result.effectiveCoeff[m.j] * current.lambda) / 1000,
            ].join(","),
          ),
        ].join("\n");
      if (csvKind === "mtf")
        content = [
          "frequenza_cicli_mm,MTF_X,MTF_Y,MTF_ideale",
          ...Array.from(result.cuts.x, (value, k) =>
            [
              (1000 * k) / (result.n * current.pitch),
              value,
              result.cuts.y[k],
              result.idealCuts.x[k],
            ].join(","),
          ),
        ].join("\n");
      if (csvKind === "wave")
        content = [
          "x_norm,y_norm,W_lambda,W_um",
          ...Array.from(result.wave.data, (w, i) =>
            Number.isFinite(w)
              ? [
                  (2 * ((i % result.wave.size) + 0.5)) / result.wave.size - 1,
                  1 -
                    (2 * (Math.floor(i / result.wave.size) + 0.5)) /
                      result.wave.size,
                  w,
                  (w * current.lambda) / 1000,
                ].join(",")
              : null,
          ).filter(Boolean),
        ].join("\n");
      if (csvKind === "psf") {
        const raw = await exportData("psf"),
          chunks = [meta, "x_um,y_um,PSF_energia_normalizzata\n"];
        for (let row = 0; row < raw.n; row++) {
          const lines = [];
          for (let col = 0; col < raw.n; col++) {
            const index =
              ((row + raw.n / 2) % raw.n) * raw.n + ((col + raw.n / 2) % raw.n);
            lines.push(
              [
                (col - raw.n / 2) * current.pitch,
                (row - raw.n / 2) * current.pitch,
                raw.values[index],
              ].join(","),
            );
          }
          chunks.push(lines.join("\n") + "\n");
          if (row % 32 === 0)
            await new Promise((resolve) => setTimeout(resolve, 0));
        }
        downloadBlob(
          new Blob(chunks, { type: "text/csv;charset=utf-8" }),
          "zernike-psf.csv",
        );
      } else
        downloadBlob(
          new Blob([meta, content], { type: "text/csv;charset=utf-8" }),
          `zernike-${csvKind}.csv`,
        );
    } catch (e) {
      toast(e.message);
    } finally {
      setExporting(false);
    }
  }
  const psfHandlers = {
    onWheel: (e) =>
      update({
        psfZoom: Math.max(
          1,
          Math.min(64, p.psfZoom * (e.deltaY > 0 ? 1 / 1.12 : 1.12)),
        ),
      }),
    onPointerDown: (e) => {
      e.currentTarget.setPointerCapture(e.pointerId);
      drag.current = { x: e.clientX, y: e.clientY, px: p.psfX, py: p.psfY };
    },
    onPointerMove: (e) => {
      if (!drag.current || !result) return;
      const rect = e.currentTarget.getBoundingClientRect(),
        d = drag.current;
      update({
        psfX: d.px - ((e.clientX - d.x) * result.n) / (rect.width * p.psfZoom),
        psfY: d.py - ((e.clientY - d.y) * result.n) / (rect.height * p.psfZoom),
      });
    },
    onPointerUp: () => {
      drag.current = null;
    },
  };
  const controls = (
    <ZernikeControls
      view={view}
      animation={animation}
      setAnimation={setAnimation}
      autoCapture={autoCapture}
      setAutoCapture={setAutoCapture}
      strength={strength}
      setStrength={setStrength}
      newAtmosphere={newAtmosphere}
    />
  );
  const metricItems = result
    ? [
        {
          label: "RMS del fronte",
          value: format(result.wave.rms),
          unit: "λ",
          entry: H.rms,
        },
        {
          label: "Peak-to-Valley",
          value: format(result.wave.pv),
          unit: "λ",
          entry: H.pv,
        },
        {
          label: "Strehl campionato",
          value: format(result.strehl, 4),
          entry: H.strehl,
        },
        {
          label: "Cutoff incoerente",
          value: format(result.sampling.cutoff, 1),
          unit: "cicli/mm",
          entry: H.cutoff,
        },
        {
          label: "Calcolo",
          value: format(result.ms, 1),
          unit: "ms",
          entry: H.compute,
        },
      ]
    : [];
  return (
    <Workspace controls={controls}>
      <div className="page-heading">
        <div>
          <span className="eyebrow">
            Laboratorio 02 · Formazione dell’immagine
          </span>
          <h1>Simulatore Aberrazioni Zernike</h1>
          <p>Un fronte d’onda. Quindici modi. La qualità dell’immagine.</p>
        </div>
        <ExportBar
          disabled={!ready || exporting || view === "quiz"}
          onPNG={() =>
            downloadCanvas(
              resultRef.current || psfRef.current,
              "zernike-immagine.png",
            )
          }
          onCSV={exportCSV}
          onSVG={() =>
            downloadBlob(
              reportSVG({
                title: "Aberrazioni Zernike",
                params: current,
                panels: panels().filter((panel) => panel.title !== "MTF"),
                series,
                xMax: result.sampling.cutoff,
                xLabel: "Frequenza spaziale (cicli/mm)",
                yLabel: "Contrasto residuo",
              }),
              "zernike-report.svg",
            )
          }
          onScreenshot={() => downloadCanvas(report(), "zernike-report.png")}
        />
      </div>
      <div className="view-toolbar">
        <Tabs
          items={viewTabs}
          value={view}
          onChange={changeView}
          label="Modalità Zernike"
        />
        <span className="backend-label">{busy ? "Calcolo…" : backend}</span>
      </div>
      {sourceError && <Notice tone="error">{sourceError}</Notice>}
      {error && (
        <Notice tone="error">
          {error} I pannelli mostrano l’ultima condizione valida; non descrivono
          i parametri attuali.
        </Notice>
      )}
      {!result && !error && (
        <Notice>
          Preparazione dell’immagine e inizializzazione del motore FFT…
        </Notice>
      )}
      {exporting && <Notice>Esportazione dei campioni numerici…</Notice>}
      {view !== "quiz" && <Metrics items={metricItems} />}
      <div className="engine-settings">
        <SelectControl
          label="Dati da esportare in CSV"
          value={csvKind}
          onChange={setCsvKind}
          options={[
            ["mtf", "MTF · frequenze fisiche"],
            ["coeff", "Coefficienti di Zernike"],
            ["wave", "Fronte d’onda · pupilla"],
            ["psf", "PSF completa · N² campioni"],
          ]}
          entry={H.csvKind}
        />
        <Toggle
          label="Forza FFT su CPU"
          checked={forceCPU}
          onChange={setForceCPU}
          entry={help(
            "Motore di calcolo",
            "La GPU WebGL2 viene usata se supporta texture Float32 e framebuffer adeguati.",
            "Forzare la CPU usa FFT Float64 nel worker: utile per confronti numerici; può richiedere più tempo.",
            "Le formule sono le stesse. Il tempo dipende dal dispositivo e dalla dimensione FFT.",
          )}
        />
      </div>
      {view === "quiz" && (
        <LearningQuiz onGenerate={generateQuiz} answer={answer} busy={!ready} />
      )}
      {result && (
        <>
          {view === "fourier" && (
            <>
              <div
                className="fourier-chain"
                aria-label="Catena di formazione dell’immagine"
              >
                {[
                  "P = A exp(i2πW/λ)",
                  "FFT → |·|²",
                  "PSF normalizzata",
                  "FFT → OTF",
                  "|OTF| → MTF",
                  "Oggetto ∗ PSF",
                ].map((label, i) => (
                  <span key={label}>
                    {i > 0 && <ArrowRight size={16} />}
                    <b>{label}</b>
                  </span>
                ))}
              </div>
              <div className="two-grid">
                <Panel title="Pupilla complessa P" kicker="Ampiezza × fase">
                  <Pupil map={result.wave} />
                  <p className="panel-note">
                    Ampiezza 1 nel disco, 0 fuori. La tonalità ciclica
                    rappresenta la fase modulo 2π; un ciclo di colore equivale a
                    1 λ.
                  </p>
                </Panel>
                <Panel
                  title="Optical Transfer Function"
                  kicker="Trasformata della PSF"
                >
                  <CanvasImage
                    ref={otfRef}
                    source={images.otf}
                    label="OTF: fase in colore, modulo in luminosità"
                  />
                  <p className="panel-note">
                    Fase in tonalità, modulo in luminosità. OTF(0) ={" "}
                    {format(result.otfDC[0], 5)} + i{format(result.otfDC[1], 5)}
                    . La MTF è il modulo, non la parte reale.
                  </p>
                </Panel>
              </div>
            </>
          )}
          {view === "compare" && result.extra && (
            <section className="comparison-columns">
              {[
                {
                  name: "Sistema ideale",
                  caption: "Tutti i coefficienti nulli",
                  psf: images.idealPsf,
                  image: images.idealResult,
                  strehl: 1,
                },
                {
                  name: "Aberrazione singola",
                  caption: `${MODES[current.comparisonMode].name} = ${current.comparisonAmplitude} λ`,
                  psf: result.extra.psf,
                  image: result.extra.result,
                  strehl: result.extra.strehl,
                },
                {
                  name: "Aberrazioni combinate",
                  caption: "Somma dei coefficienti del pannello",
                  psf: images.psf,
                  image: images.result,
                  strehl: result.strehl,
                },
              ].map((item) => (
                <Panel key={item.name} title={item.name} kicker={item.caption}>
                  <CanvasImage source={item.psf} label={`PSF · ${item.name}`} />
                  <CanvasImage
                    source={item.image}
                    label={`Immagine · ${item.name}`}
                  />
                  <p className="panel-note">
                    Strehl campionato {format(item.strehl, 4)}
                  </p>
                </Panel>
              ))}
            </section>
          )}
          {view === "ao" && result.extra && (
            <>
              <Notice>
                Correzione modale ideale: a′ⱼ = (1 − g)aⱼ per 1 ≤ j ≤{" "}
                {current.aoOrder}. Il pistone resta escluso. Gli slider
                descrivono il fronte introdotto; i pannelli principali mostrano
                il fronte corretto.
              </Notice>
              <div className="two-grid">
                <Panel
                  title="Prima della correzione"
                  kicker={`Strehl ${format(result.extra.strehl, 4)}`}
                >
                  <div className="two-grid compact">
                    <WaveMap map={result.beforeWave} />
                    <CanvasImage
                      source={result.extra.psf}
                      label="PSF prima della correzione"
                    />
                  </div>
                  <CanvasImage
                    source={result.extra.result}
                    label="Immagine prima della correzione"
                  />
                </Panel>
                <Panel
                  title="Dopo la correzione"
                  kicker={`Strehl ${format(result.strehl, 4)} · guadagno ${(result.strehl / Math.max(1e-9, result.extra.strehl)).toFixed(2)}×`}
                >
                  <div className="two-grid compact">
                    <WaveMap map={result.wave} />
                    <CanvasImage source={images.psf} label="PSF corretta" />
                  </div>
                  <CanvasImage
                    source={images.result}
                    label="Immagine dopo la correzione"
                  />
                </Panel>
              </div>
            </>
          )}
          <div
            className={`science-grid ${error ? "invalid-stage" : ""} ${busy ? "updating" : ""}`}
            aria-busy={busy}
          >
            <Panel
              title="Immagine originale"
              kicker="01 · Oggetto in luminanza"
            >
              <CanvasImage
                ref={originalRef}
                source={result.source}
                label="Oggetto originale, campionato in luminanza lineare"
              />
              <p className="panel-note">
                {current.resolution} × {current.resolution} px · passo{" "}
                {format(current.pitch)} µm/px. Convoluzione di intensità per
                formazione incoerente.
              </p>
            </Panel>
            <Panel
              title="Fronte d’onda"
              kicker="02 · Pupilla normalizzata"
              actions={<Help entry={H.rms} />}
            >
              <WaveMap ref={waveRef} map={result.wave} />
              <p className="panel-note">
                W = Σ aⱼ Zⱼ · x, y normalizzati.{" "}
                {view === "quiz"
                  ? "Identifica la struttura e il segno del modo."
                  : `RMS ${format((result.wave.rms * current.lambda) / 1000)} µm; pistone escluso.`}
              </p>
            </Panel>
            <Panel
              title="Point Spread Function"
              kicker="03 · |FFT(P)|²"
              actions={
                <>
                  <button
                    className="icon-button"
                    aria-label="Ingrandisci PSF"
                    onClick={() =>
                      update({ psfZoom: Math.min(64, p.psfZoom * 1.25) })
                    }
                  >
                    <ZoomIn size={16} />
                  </button>
                  <button
                    className="icon-button"
                    aria-label="Riduci PSF"
                    onClick={() =>
                      update({ psfZoom: Math.max(1, p.psfZoom / 1.25) })
                    }
                  >
                    <ZoomOut size={16} />
                  </button>
                  <Help entry={H.psfScale} />
                </>
              }
            >
              <div className="psf-container">
                <CanvasImage
                  ref={psfRef}
                  source={images.psf}
                  label="PSF aberrata, zoom e pan interattivi"
                  {...psfHandlers}
                />
                <div className="ideal-inset">
                  <CanvasImage
                    ref={idealRef}
                    source={images.idealPsf}
                    label="PSF ideale del disco di Airy"
                  />
                  <span>Airy ideale</span>
                </div>
              </div>
              <p className="panel-note">
                {current.log
                  ? `log₁₀ · ${current.psfRange} decadi`
                  : "Scala lineare"}{" "}
                · campo{" "}
                {format((result.n * current.pitch) / current.psfZoom, 2)} µm ·
                picco {format(result.peak, 6)}
                <Help entry={H.peak} />
              </p>
            </Panel>
            <Panel
              title="Modulation Transfer Function"
              kicker="04 · Contrasto residuo"
              className="mtf-panel"
              actions={
                <button
                  className="button small"
                  disabled={!ready || view === "quiz"}
                  onClick={holdCurve}
                >
                  <Plus size={14} /> Fissa curva X
                </button>
              }
            >
              <LineChart
                ref={chartRef}
                series={series}
                xLabel="Frequenza spaziale (cicli/mm)"
                yLabel="MTF · contrasto residuo"
                xMax={result.sampling.cutoff}
                yMax={1.02}
                theme={theme}
              />
              <p className="panel-note">
                Le sezioni X e Y evidenziano l’anisotropia. Il limite ideale usa
                la stessa pupilla discreta. Nyquist:{" "}
                {format(result.sampling.nyquist, 1)} cicli/mm.
              </p>
              {held.map((item, i) => (
                <button
                  key={`${item.label}-${i}`}
                  className="curve-chip"
                  style={{ color: heldColors[i] }}
                  onClick={() =>
                    setHeld((old) => old.filter((_, k) => k !== i))
                  }
                >
                  <Trash2 size={12} />
                  {item.label}
                </button>
              ))}
            </Panel>
            <Panel
              title="Immagine risultante"
              kicker="05 · Oggetto ∗ PSF"
              className="image-result-panel"
            >
              <ImageComparison
                original={result.source}
                result={images.result}
                split={p.split}
                onSplit={(split) => update({ split })}
                mode={imageMode}
                onMode={setImageMode}
                resultRef={resultRef}
              />
              <p className="panel-note">
                PSF normalizzata a energia unitaria · ΣPSF ={" "}
                {format(result.energy, 5)}. I dati vengono convoluti in luce
                lineare e poi ricodificati per lo schermo.
              </p>
            </Panel>
          </div>
          {view !== "quiz" && (
            <section className="panel contribution-panel">
              <details onToggle={(e) => setContributions(e.currentTarget.open)}>
                <summary>
                  Contributi individuali al fronte d’onda{" "}
                  <span className="muted">· somma lineare dei modi attivi</span>
                </summary>
                <div className="contribution-grid">
                  {individual.length ? (
                    individual.map((item) => (
                      <div key={item.j}>
                        <WaveMap
                          map={item.map}
                          limit={Math.max(
                            Math.abs(result.wave.min),
                            Math.abs(result.wave.max),
                            0.01,
                          )}
                        />
                        <p>
                          {MODES[item.j].name}
                          <br />
                          <strong>{format(item.a)} λ</strong>
                        </p>
                      </div>
                    ))
                  ) : (
                    <p>Nessun modo attivo: fronte piano.</p>
                  )}
                </div>
              </details>
            </section>
          )}
          {captures.length > 0 && (
            <Panel
              title="Acquisizioni automatiche"
              kicker="Ultimi sei fotogrammi · salvati in memoria"
            >
              <div className="capture-gallery">
                {captures.map((capture, i) => (
                  <a
                    key={`${capture.rms}-${i}`}
                    href={capture.url}
                    download={`zernike-fotogramma-${i + 1}.png`}
                  >
                    <img
                      src={capture.url}
                      alt={`Fotogramma con RMS ${capture.rms.toFixed(3)} lambda`}
                    />
                    <span>RMS {format(capture.rms)} λ · scarica PNG</span>
                  </a>
                ))}
              </div>
              <button className="text-button" onClick={() => setCaptures([])}>
                Svuota acquisizioni
              </button>
            </Panel>
          )}
        </>
      )}
      <ExplorationGuide guide={explorationGuide} />
    </Workspace>
  );
}
