import { useState } from "react";
import { NumberControl, SelectControl, Notice, Help } from "../ui/Controls.jsx";
import { MODES } from "../../services/zernike/zernike.js";
import { parameterHelp as H } from "../../utils/zernike-learning.js";
export function LearningQuiz({ onGenerate, answer, busy }) {
  const [type, setType] = useState(4),
    [sign, setSign] = useState("positive"),
    [amplitude, setAmplitude] = useState(0.5),
    [revealed, setRevealed] = useState(false);
  return (
    <section className="panel quiz-panel">
      <div className="panel-heading">
        <div>
          <span className="eyebrow">Modalità apprendimento</span>
          <h2>Riconosci il fronte nascosto</h2>
        </div>
        <button
          className="button primary"
          onClick={() => {
            setRevealed(false);
            onGenerate();
          }}
        >
          Nuova sfida
        </button>
      </div>
      <p>
        Osserva fronte d’onda, PSF e MTF. Il segno di alcuni modi non si
        distingue dalla sola intensità: usa la mappa con la sua scala.
      </p>
      <div className="quiz-fields">
        <SelectControl
          label="Tipo di aberrazione"
          value={type}
          onChange={(v) => setType(Number(v))}
          options={MODES.slice(3).map((m) => [m.j, m.name])}
          entry={H.quizType}
        />
        <SelectControl
          label="Segno"
          value={sign}
          onChange={setSign}
          options={[
            ["positive", "Positivo"],
            ["negative", "Negativo"],
          ]}
          entry={H.quizSign}
        />
        <NumberControl
          label="Ampiezza stimata"
          value={amplitude}
          onChange={setAmplitude}
          min={0.1}
          max={1.5}
          step={0.1}
          unit="λ"
          entry={H.quizAmplitude}
        />
      </div>
      <button
        className="button"
        disabled={!answer || busy}
        onClick={() => setRevealed(true)}
      >
        Verifica risposta
      </button>
      {revealed && answer && (
        <Notice
          tone={
            type === answer.j &&
            sign === (answer.a > 0 ? "positive" : "negative") &&
            Math.abs(amplitude - Math.abs(answer.a)) <= 0.2
              ? "success"
              : "info"
          }
        >
          Soluzione:{" "}
          <strong>
            {MODES[answer.j].name}, {answer.a > 0 ? "+" : ""}
            {answer.a.toFixed(1)} λ
          </strong>
          . Tipo {type === answer.j ? "corretto" : "da rivedere"}; segno{" "}
          {sign === (answer.a > 0 ? "positive" : "negative")
            ? "corretto"
            : "da rivedere"}
          ; errore sull’ampiezza{" "}
          {Math.abs(amplitude - Math.abs(answer.a)).toFixed(1)} λ (tolleranza
          0,2 λ).
        </Notice>
      )}
    </section>
  );
}
