import { useRef, useLayoutEffect } from "react";
import { CanvasImage } from "./CanvasImage.jsx";
import { NumberControl, Tabs, Help } from "../ui/Controls.jsx";
import { parameterHelp as H } from "../../utils/zernike-learning.js";
export function ImageComparison({
  original,
  result,
  split,
  onSplit,
  mode,
  onMode,
  originalRef,
  resultRef,
}) {
  return (
    <>
      <div className="comparison-view-controls">
        <Help entry={H.resultView} />
        <Tabs
          label="Confronto immagine"
          value={mode}
          onChange={onMode}
          items={[
            ["split", "Prima / dopo"],
            ["side", "Affiancate"],
            ["result", "Solo risultato"],
          ]}
        />
      </div>
      <div className={`image-comparison ${mode}`}>
        <div className="original-layer">
          <CanvasImage
            ref={originalRef}
            source={original}
            label="Immagine originale in luminanza"
          />
          <span className="image-label">Originale</span>
        </div>
        <div
          className="result-layer"
          style={
            mode === "split"
              ? { clipPath: `inset(0 0 0 ${split}%)` }
              : undefined
          }
        >
          <CanvasImage
            ref={resultRef}
            source={result}
            label="Immagine convoluta con la PSF"
          />
          <span className="image-label">Risultato</span>
        </div>
        {mode === "split" && (
          <div className="split-line" style={{ left: `${split}%` }} />
        )}
      </div>
      {mode === "split" && (
        <NumberControl
          label="Confronto prima / dopo"
          value={split}
          onChange={onSplit}
          min={0}
          max={100}
          step={1}
          unit="%"
          entry={H.split}
        />
      )}
    </>
  );
}
export function Pupil({ map }) {
  const ref = useRef(null);
  useLayoutEffect(() => {
    if (!map) return;
    const c = ref.current;
    c.width = c.height = map.size;
    const ctx = c.getContext("2d"),
      image = ctx.createImageData(map.size, map.size);
    for (let i = 0; i < map.data.length; i++) {
      const w = map.data[i];
      let rgb = [7, 13, 21];
      if (Number.isFinite(w)) {
        const phase = ((w % 1) + 1) % 1;
        rgb = [0, 2 / 3, 1 / 3].map((offset) =>
          Math.round(
            255 *
              Math.max(
                0,
                Math.min(1, Math.abs(((phase + offset) % 1) * 6 - 3) - 1),
              ),
          ),
        );
      }
      image.data.set([...rgb, 255], i * 4);
    }
    ctx.putImageData(image, 0, 0);
  }, [map]);
  return (
    <canvas
      ref={ref}
      className="scientific-canvas"
      role="img"
      aria-label="Pupilla complessa: ampiezza unitaria nel disco, fase in tonalità cicliche"
    />
  );
}
